"""Native-size RGB/depth generated by the pinned observe fixture, no camera or model."""
import json
import tempfile
from pathlib import Path

import perceive
import sofa_check as sc
import source


class Scene:
    def __init__(self):
        self.scratch = tempfile.TemporaryDirectory(prefix="den-evidence-")
        self.path = Path(self.scratch.name)
        self.tools = perceive.Tools(sc.archive(self.path, "observe"), sc.archive(self.path, "track"))
        import fake_detector
        import synth

        self.synth, self.fake_detector = synth, fake_detector
        self.scene = synth.Scene()
        self.depth = self.scene.depth_mm()
        self.pixels = {}
        for name, (x, z) in synth.JOINTS.items():
            xyz = (x, synth.PANEL_Y, max(0.12, z - 0.4))
            left = synth.g.apply(*self.scene.left_from_room, xyz)
            rgb = synth.g.apply(*synth.RGB_FROM_LEFT, left)
            self.pixels[name] = synth.g.project(rgb, self.scene.k_rgb, self.scene.d_rgb)
        self.room = self.path / "room.json"
        self.room.write_text(json.dumps(synth.room_model()), encoding="utf-8")
        self.method = perceive.track_method_copy(self.tools, [-2.0, -1.0, 5.0, 6.0], self.path)
        self.now = 1_800_000_000.0

    def perceiver(self):
        return perceive.Perceiver(self.tools, room_model_path=self.room, camera_id="den-oak",
                                  max_error_bound_m=0.1, track_method_path=self.method, home="den",
                                  now=lambda: self.now)

    def sample(self, at, seq, *, session="oak-1", extra=False, empty=False, luma=120, skew=0.0, arrival=None):
        native = at + 5000.0
        meta = self.synth.metadata(session, seq, native, native - skew,
                                   {"rgb": self.synth.RGB_K, "depth": self.synth.LEFT_K})
        meta["depth_correction"] = {"applied": True, "calibration_sha256": "synthetic-eeprom", "factor": 0.889}
        row = self.fake_detector.row(native, rgb_seq=seq, pixels=self.pixels)
        if empty:
            row["detections"].clear()
        if extra:
            row["detections"].append({"id": "rival", "class": "person", "score": 0.88,
                                      "box_xyxy": [5.0, 8.0, 65.0, 40.0], "keypoints": None})
        arrival = at if arrival is None else arrival
        bundle = source.Bundle(self.synth.bundle(meta, self.depth), session, seq, native, self.now, arrival)
        return bundle, {"row": row, "luma": luma, "compute_s": 0.04}

    def close(self):
        self.scratch.cleanup()
